1	import { finding, stripComments, isSource, lineOf, balanced, wires, quoted } from './lib.mjs';
2	
3	// Speaking is asynchronous, and both browser TTS engines end an utterance in
4	// more ways than "it finished". A caller that awaits completion — anything with
5	// a speak promise, a queue that waits its turn, a UI that re-enables on done —
6	// settles only if its handler treats EVERY terminal outcome as an ending:
7	//
8	//   • chrome.tts fires onEvent with type 'end' | 'interrupted' | 'cancelled' |
9	//     'error'. `interrupted` arrives whenever a later speak() with enqueue:false
10	//     displaces this utterance, and `cancelled` whenever it is dropped from the
11	//     queue before it starts (a tts.stop(), a teardown, a barge-in). In any app
12	//     that can speak twice or stop early — which is most of them — those are
13	//     ordinary endings, not edge cases, so a handler resolving on 'end' alone
14	//     hangs on the COMMON path.
15	//   • speechSynthesis reports a failed utterance through `error` and never
16	//     through `end`, so an utterance wired for end alone hangs on every failure.
17	//
18	// The failure is silent by construction: nothing throws, nothing logs, the
19	// promise simply never settles. Whatever the caller was going to do next — speak
20	// the next item, reopen the mic, drop a spinner — never happens.
21	//
22	// PARSED, NOT GREPPED, and deliberately narrow in two ways:
23	//   1. Only the balanced argument list of a `.speak(` call is read, and only when
24	//      that call actually supplies an `onEvent` handler — so a wrapper's own
25	//      `tts.speak(text, {rate})` (the wrapper owns the terminal handling) and any
26	//      unrelated `.speak(` stay quiet.
27	//   2. A handler is judged only if it enumerates terminal types INLINE (it quotes
28	//      at least one of them). One that delegates to a hoisted set or table —
29	//      `if (TERMINAL.has(e.type)) resolve()` — is not something this rule can
30	//      read, so it says nothing rather than guessing; a check that guesses is
31	//      worse than one that asks a simple, honest question.
32	// Comments are stripped first, so the paragraphs above can't fire the rule.
33	
34	const TTS_TERMINAL = ['end', 'interrupted', 'cancelled', 'error'];
35	const SPEAK_CALL = /\.\s*speak\s*\(/g;
36	const UTTERANCE = /\bSpeechSynthesisUtterance\b/;
37	
38	const rule = {
39	  id: 'tts-speak-settles',
40	  severity: 'blocking',
41	  description: 'A TTS completion handler settles on every terminal outcome, not just "end"',
42	  doc: '.claudinite/local/packs/browser-speech/RULES.md',
43	  why: 'a speak promise settles only from the outcome its handler recognises, so one that ignores interrupted/cancelled/error leaves every awaiting caller pending forever — with nothing thrown and nothing logged',
44	
45	  run(ctx) {
46	    const out = [];
47	    for (const file of ctx.files) {
48	      if (!isSource(file)) continue;
49	      const raw = ctx.read(file);
50	      if (raw === null) continue;
51	      const src = stripComments(raw);
52	
53	      // chrome.tts.speak(text, { onEvent(e) { … } })
54	      SPEAK_CALL.lastIndex = 0;
55	      for (let m = SPEAK_CALL.exec(src); m; m = SPEAK_CALL.exec(src)) {
56	        const args = balanced(src, m.index + m[0].length - 1);
57	        if (args === null || !/\bonEvent\b/.test(args)) continue;
58	        const missing = TTS_TERMINAL.filter((type) => !quoted(args, type));
59	        // Enumerates none inline → it is delegating, not forgetting. Say nothing.
60	        if (missing.length === 0 || missing.length === TTS_TERMINAL.length) continue;
61	        out.push(finding(rule, {
62	          file,
63	          line: lineOf(src, m.index),
64	          what: `a chrome.tts speak handler never settles on ${missing.join('/')}`,
65	          fix: `treat every terminal event as completion — resolve on ${TTS_TERMINAL.join(', ')} alike; a later speak() with enqueue:false ends this utterance as 'interrupted' and a stop()/teardown as 'cancelled', so those are normal endings, not rare ones`,
66	        }));
67	      }
68	
69	      // new SpeechSynthesisUtterance(text) — wired for end without error
70	      if (UTTERANCE.test(src) && wires(src, 'end') && !wires(src, 'error')) {
71	        out.push(finding(rule, {
72	          file,
73	          line: lineOf(src, src.search(UTTERANCE)),
74	          what: 'a SpeechSynthesisUtterance settles on end but has no error handler',
75	          fix: "handle the utterance's error event alongside end and settle the same promise from both (either wiring form — `utterance.onerror =` or `addEventListener('error', …)`) — speechSynthesis reports a failed utterance through error only, so end never fires and the awaiting caller hangs",
76	        }));
77	      }
78	    }
79	    return out;
80	  },
81	};
82	
83	export default rule;
84

