1	import { finding, stripComments, isSource, lineOf, wires } from './lib.mjs';
2	
3	// The mirror of tts-speak-settles on the input side. A recognition cycle has
4	// three ways to finish, only one of which is `result`:
5	//   • result — the engine produced a transcript;
6	//   • error  — a named taxonomy of failures (not-allowed, no-speech, network,
7	//              aborted, audio-capture); `aborted` in particular arrives on every
8	//              stop() and every barge-in, i.e. routinely;
9	//   • end    — the recognizer closed with NOTHING. This is the one that gets
10	//              forgotten, and it is not rare: a silent user, an endpoint the
11	//              engine gave up on, an OS-level device grab. The browser fires
12	//              only `end` there — no result, no error.
13	//
14	// A recognizer wired for `result` alone therefore leaves its cycle pending on
15	// two of its three exits. Nothing throws and nothing logs; the UI still shows a
16	// live mic while the recognizer is closed and deaf, and only the user notices.
17	// Continuous recognizers are no exception — they need `end` to restart on and
18	// `error` to stop retrying on, or they die just as quietly.
19	//
20	// `onresult` / addEventListener('result') is Web-Speech-only, so the wiring is
21	// the whole trigger — no need to guess at the constructor, which is variously
22	// `SpeechRecognition`, `webkitSpeechRecognition`, or an injected seam. Both DOM
23	// wiring forms count (see `wires`): a file mixing `rec.onresult =` with
24	// `rec.addEventListener('error', …)` is correctly wired and must stay quiet.
25	// Comments are stripped first, so a comment naming onresult can't fire the rule.
26	
27	const rule = {
28	  id: 'stt-terminal-handlers',
29	  severity: 'blocking',
30	  description: 'A speech recognizer handles the end and error events, not just result',
31	  doc: '.claudinite/local/packs/browser-speech/RULES.md',
32	  why: 'a recognition cycle that ends with no transcript fires only `end`, so a recognizer wired for result alone leaves the listen promise pending forever — the UI shows a live mic while nothing is listening, with no error anywhere',
33	
34	  run(ctx) {
35	    const out = [];
36	    for (const file of ctx.files) {
37	      if (!isSource(file)) continue;
38	      const raw = ctx.read(file);
39	      if (raw === null || !raw.includes('result')) continue;
40	      const src = stripComments(raw);
41	      if (!wires(src, 'result')) continue;
42	      const missing = ['end', 'error'].filter((event) => !wires(src, event));
43	      if (missing.length === 0) continue;
44	      out.push(finding(rule, {
45	        file,
46	        line: lineOf(src, src.search(/\.\s*onresult\s*=|addEventListener\s*\(\s*['"`]result['"`]/)),
47	        what: `a speech recognizer handles result but never ${missing.join(' or ')}`,
