51	const SWITCH = /\bswitch\s*\(/g;
52	const CASE = /^case\s+(['"`])([^'"`]*)\1\s*:/;
53	const DEFAULT = /^default\s*:/;
54	
55	/**
56	 * The case labels and `default:` presence at a switch body's own brace depth.
57	 * `body` is the balanced `{…}` run including both braces. Depth-aware so a nested
58	 * switch inside one arm contributes neither its labels nor its default; string and
59	 * template literals are skipped so a colon inside `"a:b"` can't read as syntax.
60	 */
61	function arms(body) {
62	  const labels = new Set();
63	  let hasDefault = false;
64	  let depth = 0;
65	  for (let i = 1; i < body.length - 1; i++) {
66	    const c = body[i];
67	    if (c === '"' || c === "'" || c === '`') {
68	      const quote = c;
69	      for (i += 1; i < body.length; i++) {
70	        if (body[i] === '\\') { i += 1; continue; }
71	        if (body[i] === quote) break;
72	      }
73	      continue;
74	    }
75	    if (c === '{' || c === '[' || c === '(') { depth += 1; continue; }
76	    if (c === '}' || c === ']' || c === ')') { depth -= 1; continue; }
77	    if (depth !== 0 || /[\w$]/.test(body[i - 1])) continue;
78	    const rest = body.slice(i);
79	    const label = CASE.exec(rest);
80	    if (label) {
81	      labels.add(label[2]);
82	      i += label[0].length - 1;
83	      continue;
84	    }
85	    if (DEFAULT.test(rest)) hasDefault = true;
86	  }
87	  return { labels, hasDefault };
88	}
89	
90	const rule = {
91	  id: 'stt-error-map-has-default',
92	  severity: 'blocking',
93	  description: 'A speech-recognition error mapping is total — every name maps to a kind',
94	  doc: '.claudinite/local/packs/browser-speech/RULES.md',
95	  why: 'the Web Speech error-name set is open — browsers extend it — so a mapping switch with no catch-all returns undefined for a name it does not enumerate; the dialog policy then compares undefined against every kind it knows, takes its do-nothing arm, and the session dies without throwing, logging, or changing the UI',
96	
97	  run(ctx) {
98	    const out = [];
99	    for (const file of ctx.files) {
100	      if (!isSource(file)) continue;
101	      const raw = ctx.read(file);
102	      if (raw === null) continue;
103	      if (ERROR_NAMES.filter((name) => raw.includes(name)).length < 2) continue;
104	      const src = stripComments(raw);
105	      SWITCH.lastIndex = 0;
106	      for (let m = SWITCH.exec(src); m; m = SWITCH.exec(src)) {
107	        const parenAt = m.index + m[0].length - 1;
108	        const head = balanced(src, parenAt);
109	        if (head === null) continue;
110	        const braceAt = src.indexOf('{', parenAt + head.length);
111	        if (braceAt === -1 || src.slice(parenAt + head.length, braceAt).trim() !== '') continue;
112	        const body = balanced(src, braceAt);
